  'max-points-on-line': `def maxPoints(points: list[list[int]]) -> int:
    from math import gcd
    n = len(points)
    if n <= 2:
        return n
    result = 1
    for i in range(n):
        counts = {}
        local_max = 0
        for j in range(i + 1, n):
            dy = points[j][1] - points[i][1]
            dx = points[j][0] - points[i][0]
            g = gcd(abs(dy), abs(dx))
            dy //= g
            dx //= g
            if dx < 0 or (dx == 0 and dy < 0):
                dy, dx = -dy, -dx
            key = (dy, dx)
            counts[key] = counts.get(key, 0) + 1
            local_max = max(local_max, counts[key])
        result = max(result, local_max + 1)
    return result
`,

  'lru-cache': `def lruCacheRunner(capacity, ops, args):
    from collections import OrderedDict
    class LRUCache:
        def __init__(self, cap):
            self.cap = cap
            self.cache = OrderedDict()
        def get(self, key):
            if key not in self.cache:
                return -1
            self.cache.move_to_end(key)
            return self.cache[key]
        def put(self, key, value):
            if key in self.cache:
                self.cache.move_to_end(key)
                self.cache[key] = value
            else:
                if len(self.cache) >= self.cap:
                    self.cache.popitem(last=False)
                self.cache[key] = value
    cache = LRUCache(int(capacity))
    result = []
    for op, a in zip(ops, args):
        if op == 'get':
            result.append(cache.get(a[0]))
        elif op == 'put':
            cache.put(a[0], a[1])
            result.append(None)
        else:
            result.append(None)
    return result
`,

