  'maximal-rectangle': `
def maximalRectangle(matrix):
    matrix = [list(row) for row in matrix]
    if not matrix or not matrix[0]:
        return 0
    cols = len(matrix[0])
    heights = [0] * cols
    max_area = 0
    def largest_rect(h):
        stack, area = [], 0
        for i in range(len(h) + 1):
            cur = 0 if i == len(h) else h[i]
            while stack and h[stack[-1]] > cur:
                height = h[stack.pop()]
                width = i if not stack else i - stack[-1] - 1
                area = max(area, height * width)
            stack.append(i)
        return area
    for row in matrix:
        for c in range(cols):
            heights[c] = heights[c] + 1 if row[c] == '1' else 0
        max_area = max(max_area, largest_rect(heights))
    return max_area
`,

  'stone-game-iii': `
def stoneGameIII(stoneValue):
    stoneValue = list(stoneValue)
    n = len(stoneValue)
    dp = [float('-inf')] * (n + 1)
    dp[n] = 0
    for i in range(n - 1, -1, -1):
        s = 0
        for k in range(1, 4):
            if i + k > n:
                break
            s += stoneValue[i + k - 1]
            dp[i] = max(dp[i], s - dp[i + k])
    if dp[0] > 0:
        return 'Alice'
    elif dp[0] < 0:
        return 'Bob'
    return 'Tie'
`,

  'maximum-profit-job-scheduling': `
def jobScheduling(startTime, endTime, profit):
    import bisect
    startTime = list(startTime)
    endTime = list(endTime)
    profit = list(profit)
    jobs = sorted(zip(endTime, startTime, profit))
    ends = [j[0] for j in jobs]
    dp = [0] * (len(jobs) + 1)
    for i, (end, start, p) in enumerate(jobs):
        j = bisect.bisect_right(ends, start)
        dp[i + 1] = max(dp[i], p + dp[j])
    return dp[len(jobs)]
`,

