  'minimum-score-triangulation': `
def minScoreTriangulation(values):
    n = len(values)
    dp = [[0] * n for _ in range(n)]
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i + 1, j):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j] + values[i] * values[k] * values[j])
    return dp[0][n - 1]
`,

  'score-after-flipping-matrix': `
def matrixScore(grid):
    if hasattr(grid, 'to_py'):
        g = [list(row) for row in grid.to_py()]
    else:
        g = [list(row) for row in grid]
    m, n = len(g), len(g[0])
    for i in range(m):
        if g[i][0] == 0:
            g[i] = [1 - x for x in g[i]]
    for j in range(1, n):
        ones = sum(g[i][j] for i in range(m))
        if ones < m - ones:
            for i in range(m):
                g[i][j] = 1 - g[i][j]
    total = 0
    for i in range(m):
        row = 0
        for j in range(n):
            row = (row << 1) | g[i][j]
        total += row
    return total
`,

  'beautiful-array': `
def beautifulArray(n):
    from math import ceil, floor
    memo = {}
    def ba(k):
        if k in memo:
            return memo[k]
        if k == 1:
            return [1]
        left = ba(ceil(k / 2))
        right = ba(floor(k / 2))
        result = [2*x - 1 for x in left if 2*x - 1 <= k] + [2*x for x in right if 2*x <= k]
        memo[k] = result
        return result
    return ba(n)
`,

