  'sort-an-array': `
def sortArray(nums):
    nums = list(nums.to_py()) if hasattr(nums, 'to_py') else list(nums)
    def merge(l, r):
        res = []
        i = j = 0
        while i < len(l) and j < len(r):
            if l[i] <= r[j]:
                res.append(l[i]); i += 1
            else:
                res.append(r[j]); j += 1
        return res + l[i:] + r[j:]
    def sort(arr):
        if len(arr) <= 1:
            return arr
        mid = len(arr) // 2
        return merge(sort(arr[:mid]), sort(arr[mid:]))
    return sort(nums)
`,

  'sliding-puzzle': `
def slidingPuzzle(board):
    board = [list(row.to_py()) if hasattr(row, 'to_py') else list(row) for row in (board.to_py() if hasattr(board, 'to_py') else board)]
    goal = '123450'
    start = ''.join(str(x) for row in board for x in row)
    neighbors = [[1,3],[0,2,4],[1,5],[0,4],[1,3,5],[2,4]]
    if start == goal:
        return 0
    from collections import deque
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        state, steps = queue.popleft()
        pos = state.index('0')
        for nb in neighbors[pos]:
            arr = list(state)
            arr[pos], arr[nb] = arr[nb], arr[pos]
            nxt = ''.join(arr)
            if nxt == goal:
                return steps + 1
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, steps + 1))
    return -1
`,

  'jump-game-v': `
def maxJumps(arr, d):
    arr = list(arr.to_py()) if hasattr(arr, 'to_py') else list(arr)
    n = len(arr)
    dp = [1] * n
    order = sorted(range(n), key=lambda i: arr[i])
    for i in order:
        j = i + 1
        while j <= min(i + d, n - 1):
            if arr[j] >= arr[i]:
                break
            dp[i] = max(dp[i], 1 + dp[j])
            j += 1
        j = i - 1
        while j >= max(i - d, 0):
            if arr[j] >= arr[i]:
                break
            dp[i] = max(dp[i], 1 + dp[j])
            j -= 1
    return max(dp)
`,

