  'maximum-segment-sum-after-removals': `
def maximumSegmentSum(nums, removeQueries):
    nums = list(nums.to_py()) if hasattr(nums, 'to_py') else list(nums)
    removeQueries = list(removeQueries.to_py()) if hasattr(removeQueries, 'to_py') else list(removeQueries)
    n = len(nums)
    parent = list(range(n + 1))
    seg_sum = [0] * (n + 1)
    present = [False] * n
    ans = [0] * n
    max_sum = 0

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            seg_sum[py] += seg_sum[px]

    for i in range(n - 1, -1, -1):
        ans[i] = max_sum
        idx = removeQueries[i]
        present[idx] = True
        seg_sum[idx] = nums[idx]
        if idx > 0 and present[idx - 1]:
            union(idx, idx - 1)
        if idx < n - 1 and present[idx + 1]:
            union(idx, idx + 1)
        cur_sum = seg_sum[find(idx)]
        if cur_sum > max_sum:
            max_sum = cur_sum
    return ans
`,

  'prime-palindrome': `
def primePalindrome(n):
    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    def is_palin(x):
        s = str(x)
        return s == s[::-1]

    small = [2, 3, 5, 7, 11]
    for p in small:
        if p >= n:
            return p

    for length in range(1, 10, 2):
        half = (length + 1) // 2
        start = 10 ** (half - 1)
        end = 10 ** half
        for first_half in range(start, end):
            s = str(first_half)
            pal = int(s + s[:length - half][::-1])
            if pal >= n and is_prime(pal):
                return pal
    return -1
`,

