  'zuma-game': `def findMinStep(board, hand):
    from collections import Counter
    board = str(board)
    hand = str(hand)
    hand_count = Counter(hand)

    def clean(s):
        changed = True
        while changed:
            changed = False
            i = 0
            ns = ''
            while i < len(s):
                j = i
                while j < len(s) and s[j] == s[i]:
                    j += 1
                if j - i < 3:
                    ns += s[i:j]
                else:
                    changed = True
                i = j
            s = ns
        return s

    memo = {}
    def dp(b, hc_tuple):
        b = clean(b)
        if not b:
            return 0
        key = (b, hc_tuple)
        if key in memo:
            return memo[key]
        hc = dict(hc_tuple)
        best = float('inf')
        i = 0
        while i < len(b):
            j = i
            while j < len(b) and b[j] == b[i]:
                j += 1
            color = b[i]
            cnt = j - i
            need = 3 - cnt
            if hc.get(color, 0) >= need:
                hc[color] -= need
                rest = dp(b[:i] + b[j:], tuple(sorted(hc.items())))
                hc[color] += need
                if rest != -1:
                    best = min(best, need + rest)
            i = j
        res = best if best != float('inf') else -1
        memo[key] = res
        return res

    return dp(board, tuple(sorted(hand_count.items())))
`,

