  'number-of-ways-to-arrive-at-destination': `def countPaths(n, roads):
    import heapq
    n = int(n)
    MOD = 10**9 + 7
    edges = list(roads.to_py() if hasattr(roads, 'to_py') else roads)
    adj = [[] for _ in range(n)]
    for e in edges:
        u, v, t = int(e[0]), int(e[1]), int(e[2])
        adj[u].append((v, t))
        adj[v].append((u, t))
    dist = [float('inf')] * n
    ways = [0] * n
    dist[0] = 0
    ways[0] = 1
    pq = [(0, 0)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, t in adj[u]:
            nd = d + t
            if nd < dist[v]:
                dist[v] = nd
                ways[v] = ways[u]
                heapq.heappush(pq, (nd, v))
            elif nd == dist[v]:
                ways[v] = (ways[v] + ways[u]) % MOD
    return ways[n - 1]
`,

  'reorder-routes-to-make-all-paths-lead-to-city-zero': `def minReorder(n, connections):
    from collections import deque
    n = int(n)
    conns = list(connections.to_py() if hasattr(connections, 'to_py') else connections)
    adj = [[] for _ in range(n)]
    for e in conns:
        a, b = int(e[0]), int(e[1])
        adj[a].append((b, 1))
        adj[b].append((a, 0))
    visited = [False] * n
    q = deque([0])
    visited[0] = True
    count = 0
    while q:
        u = q.popleft()
        for v, cost in adj[u]:
            if not visited[v]:
                visited[v] = True
                count += cost
                q.append(v)
    return count
`,

