  'number-of-restricted-paths-from-first-to-last-node': `def countRestrictedPaths(n, edges):
    import heapq
    MOD = 10**9 + 7
    adj = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
    dist = [float('inf')] * (n + 1)
    dist[n] = 0
    pq = [(0, n)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    order = sorted(range(1, n + 1), key=lambda x: dist[x])
    dp = [0] * (n + 1)
    dp[n] = 1
    for u in order:
        for v, _ in adj[u]:
            if dist[v] < dist[u]:
                dp[u] = (dp[u] + dp[v]) % MOD
    return dp[1]
`,

  'minimum-swaps-to-sort-an-array': `def minSwaps(nums):
    n = len(nums)
    sorted_nums = sorted(nums)
    pos = {v: i for i, v in enumerate(sorted_nums)}
    visited = [False] * n
    swaps = 0
    arr = list(nums)
    for i in range(n):
        if visited[i] or pos[arr[i]] == i:
            continue
        cycle_len = 0
        j = i
        while not visited[j]:
            visited[j] = True
            j = pos[arr[j]]
            cycle_len += 1
        swaps += cycle_len - 1
    return swaps
`,

