  'count-palindromes': `
def countPalindromes(s):
    MOD = 10**9 + 7
    n = len(s)
    if n < 5:
        return 0
    digits = [int(c) for c in s]
    lp = [[0]*10 for _ in range(10)]
    ls = [0]*10
    rp = [[0]*10 for _ in range(10)]
    rs = [0]*10
    for i in range(n-1, 2, -1):
        d = digits[i]
        for b in range(10):
            rp[d][b] = (rp[d][b] + rs[b]) % MOD
        rs[d] += 1
    for i in range(2):
        d = digits[i]
        for a in range(10):
            lp[a][d] = (lp[a][d] + ls[a]) % MOD
        ls[d] += 1
    ans = 0
    for k in range(2, n-2):
        for x in range(10):
            for y in range(10):
                ans = (ans + lp[x][y] * rp[y][x]) % MOD
        if k < n-3:
            dk = digits[k]
            for a in range(10):
                lp[a][dk] = (lp[a][dk] + ls[a]) % MOD
            ls[dk] += 1
            dk1 = digits[k+1]
            rs[dk1] -= 1
            for b in range(10):
                rp[dk1][b] = (rp[dk1][b] - rs[b]) % MOD
    return ans
`,

  'longest-duplicate-substring': `
def longestDupSubstring(s):
    n = len(s)
    best = ""
    lo, hi = 1, n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        seen = set()
        found = ""
        for i in range(n - mid + 1):
            sub = s[i:i+mid]
            if sub in seen:
                found = sub
                break
            seen.add(sub)
        if found:
            best = found
            lo = mid + 1
        else:
            hi = mid - 1
    return best
`,

  'shortest-palindrome': `
def shortestPalindrome(s):
    if not s:
        return s
    t = s + "#" + s[::-1]
    fail = [0] * len(t)
    for i in range(1, len(t)):
        j = fail[i-1]
        while j > 0 and t[i] != t[j]:
            j = fail[j-1]
        if t[i] == t[j]:
            j += 1
        fail[i] = j
    k = fail[-1]
    return s[k:][::-1] + s
`,

