  'ugly-number-iii': `
def nthUglyNumber(n, a, b, c):
    from math import gcd
    def lcm(x, y): return x * y // gcd(x, y)
    ab, ac, bc = lcm(a, b), lcm(a, c), lcm(b, c)
    abc = lcm(a, bc)
    def count(x): return x//a + x//b + x//c - x//ab - x//ac - x//bc + x//abc
    lo, hi = 1, 2_000_000_000
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) < n: lo = mid + 1
        else: hi = mid
    return lo
`,

  'binary-tree-coloring-game': `
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val; self.left = left; self.right = right

def btreeGameWinningMoveRunner(n, arr, x):
    if hasattr(arr, 'to_py'):
        arr = list(arr.to_py())
    arr = [int(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else None for v in arr]
    if not arr or arr[0] is None:
        return False
    def build(i):
        if i >= len(arr) or arr[i] is None:
            return None
        return TreeNode(arr[i], build(2*i+1), build(2*i+2))
    def count_size(node):
        if not node:
            return 0
        return 1 + count_size(node.left) + count_size(node.right)
    left_count = [0]
    right_count = [0]
    def find_x(node):
        if not node:
            return
        if node.val == int(x):
            left_count[0] = count_size(node.left)
            right_count[0] = count_size(node.right)
            return
        find_x(node.left)
        find_x(node.right)
    find_x(build(0))
    rest = int(n) - left_count[0] - right_count[0] - 1
    return max(left_count[0], right_count[0], rest) > int(n) / 2
`,


