  'pyramid-transition-numbers': `
def pyramidTransition(bottom, allowed):
    if hasattr(allowed, 'to_py'):
        allowed = list(allowed.to_py())
    allowed = [str(s) for s in allowed]
    bottom = str(bottom)
    from collections import defaultdict
    mp = defaultdict(list)
    for s in allowed:
        mp[s[:2]].append(s[2])
    def build_next(row, idx, nxt):
        if idx == len(row) - 1:
            return solve(''.join(nxt))
        key = row[idx] + row[idx + 1]
        for c in mp[key]:
            nxt.append(c)
            if build_next(row, idx + 1, nxt):
                return True
            nxt.pop()
        return False
    def solve(row):
        if len(row) == 1:
            return True
        return build_next(row, 0, [])
    return solve(bottom)
`,

  'painting-a-grid-with-three-different-colors': `
def colorTheGrid(m, n):
    MOD = 10 ** 9 + 7
    max_state = 3 ** m
    valid_cols = []
    for state in range(max_state):
        s, valid, prev = state, True, -1
        for _ in range(m):
            c = s % 3
            s //= 3
            if c == prev:
                valid = False
                break
            prev = c
        if valid:
            valid_cols.append(state)
    compat = {}
    for a in valid_cols:
        compatible = []
        for b in valid_cols:
            sa, sb, ok = a, b, True
            for _ in range(m):
                if sa % 3 == sb % 3:
                    ok = False
                    break
                sa //= 3
                sb //= 3
            if ok:
                compatible.append(b)
        compat[a] = compatible
    dp = {p: 1 for p in valid_cols}
    for _ in range(1, n):
        ndp = {p: 0 for p in valid_cols}
        for q, cnt in dp.items():
            for p in compat[q]:
                ndp[p] = (ndp[p] + cnt) % MOD
        dp = ndp
    return sum(dp.values()) % MOD
`,

