  'maximum-width-of-binary-tree': `
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val; self.left = left; self.right = right

def widthOfBinaryTreeRunner(arr):
    if hasattr(arr, 'to_py'):
        arr = list(arr.to_py())
    arr = [int(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else None for v in arr]
    if not arr or arr[0] is None:
        return 0
    root = TreeNode(arr[0])
    bfs = [root]
    i = 1
    while bfs and i < len(arr):
        node = bfs.pop(0)
        if i < len(arr) and arr[i] is not None:
            node.left = TreeNode(arr[i])
            bfs.append(node.left)
        i += 1
        if i < len(arr) and arr[i] is not None:
            node.right = TreeNode(arr[i])
            bfs.append(node.right)
        i += 1
    max_width = 0
    queue = [(root, 0)]
    while queue:
        level_len = len(queue)
        left_idx = queue[0][1]
        right_idx = left_idx
        for _ in range(level_len):
            node, idx = queue.pop(0)
            ni = idx - left_idx
            right_idx = ni
            if node.left:
                queue.append((node.left, ni * 2))
            if node.right:
                queue.append((node.right, ni * 2 + 1))
        max_width = max(max_width, right_idx + 1)
    return max_width
`,

  'step-by-step-directions-from-a-binary-tree-node-to-another': `
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val; self.left = left; self.right = right

def getDirectionsRunner(arr, start_value, dest_value):
    if hasattr(arr, 'to_py'):
        arr = list(arr.to_py())
    arr = [int(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else None for v in arr]
    def build(i):
        if i >= len(arr) or arr[i] is None:
            return None
        return TreeNode(arr[i], build(2*i+1), build(2*i+2))
    def find_path(node, target, path):
        if not node:
            return False
        if node.val == target:
            return True
        path.append('L')
        if find_path(node.left, target, path):
            return True
        path.pop()
        path.append('R')
        if find_path(node.right, target, path):
            return True
        path.pop()
        return False
    root = build(0)
    start_path = []
    dest_path = []
    find_path(root, int(start_value), start_path)
    find_path(root, int(dest_value), dest_path)
    i = 0
    while i < len(start_path) and i < len(dest_path) and start_path[i] == dest_path[i]:
        i += 1
    return 'U' * (len(start_path) - i) + ''.join(dest_path[i:])
`,

