  'count-k-reducible-numbers-less-than-n': `
def countKReducibleNumbers(s, k):
    k = int(k)
    MOD = 10**9 + 7
    n = len(s)
    if k == 0:
        return 0 if s == '1' else 1
    steps = [float('inf')] * (n + 1)
    steps[1] = 0
    for c in range(2, n + 1):
        pc = bin(c).count('1')
        if steps[pc] != float('inf'):
            steps[c] = steps[pc] + 1
    C = [[0] * (n + 1) for _ in range(n + 1)]
    C[0][0] = 1
    for i in range(1, n + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
    count = [0] * (n + 1)
    prefix_ones = 0
    for i in range(n):
        if s[i] == '1':
            for c in range(1, n + 1):
                rem = c - prefix_ones
                avail = n - 1 - i
                if 0 <= rem <= avail:
                    count[c] = (count[c] + C[avail][rem]) % MOD
            prefix_ones += 1
    ans = 0
    for c in range(1, n + 1):
        if steps[c] != float('inf') and steps[c] <= k - 1:
            ans = (ans + count[c]) % MOD
    return ans`,

  'minimum-area-to-cover-all-ones-ii': `
def minimumSumOfAreas(grid):
    if hasattr(grid, 'to_py'): grid = grid.to_py()
    grid = [[int(v) for v in row] for row in grid]
    m, n = len(grid), len(grid[0])
    ps = [[0]*(n+1) for _ in range(m+1)]
    for r in range(m):
        for c in range(n):
            ps[r+1][c+1] = grid[r][c] + ps[r][c+1] + ps[r+1][c] - ps[r][c]
    def cnt(r1, r2, c1, c2):
        if r1 > r2 or c1 > c2: return 0
        return ps[r2+1][c2+1] - ps[r1][c2+1] - ps[r2+1][c1] + ps[r1][c1]
    def area(r1, r2, c1, c2):
        if r1 > r2 or c1 > c2 or cnt(r1, r2, c1, c2) == 0: return 0
        mnR, mxR, mnC, mxC = r2, r1, c2, c1
        for r in range(r1, r2+1):
            if cnt(r, r, c1, c2) > 0:
                mnR = min(mnR, r); mxR = max(mxR, r)
        for c in range(c1, c2+1):
            if cnt(r1, r2, c, c) > 0:
                mnC = min(mnC, c); mxC = max(mxC, c)
        return (mxR - mnR + 1) * (mxC - mnC + 1)
    ans = area(0, m-1, 0, n-1)
    for h1 in range(m-1):
        for h2 in range(h1+1, m):
            ans = min(ans, area(0,h1,0,n-1)+area(h1+1,h2,0,n-1)+area(h2+1,m-1,0,n-1))
    for v1 in range(n-1):
        for v2 in range(v1+1, n):
            ans = min(ans, area(0,m-1,0,v1)+area(0,m-1,v1+1,v2)+area(0,m-1,v2+1,n-1))
    for h in range(m-1):
        for v in range(n-1):
            ans = min(ans, area(0,h,0,v)+area(0,h,v+1,n-1)+area(h+1,m-1,0,n-1))
            ans = min(ans, area(0,h,0,n-1)+area(h+1,m-1,0,v)+area(h+1,m-1,v+1,n-1))
    for v in range(n-1):
        for h in range(m-1):
            ans = min(ans, area(0,h,0,v)+area(h+1,m-1,0,v)+area(0,m-1,v+1,n-1))
            ans = min(ans, area(0,m-1,0,v)+area(0,h,v+1,n-1)+area(h+1,m-1,v+1,n-1))
    return ans`,

