  'detonate-the-maximum-bombs': `def maximumDetonation(bombs):
    if hasattr(bombs, 'to_py'): bombs = list(bombs.to_py())
    bombs = [list(b.to_py()) if hasattr(b, 'to_py') else list(b) for b in bombs]
    bombs = [[int(x) for x in b] for b in bombs]
    n = len(bombs)
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            xi, yi, ri = bombs[i]
            xj, yj = bombs[j][0], bombs[j][1]
            dx, dy = xi - xj, yi - yj
            if dx*dx + dy*dy <= ri*ri:
                adj[i].append(j)
    best = 0
    for start in range(n):
        visited = {start}
        queue = [start]
        while queue:
            cur = queue.pop(0)
            for nb in adj[cur]:
                if nb not in visited:
                    visited.add(nb)
                    queue.append(nb)
        if len(visited) > best:
            best = len(visited)
    return best
`,

  'double-a-number-represented-as-linked-list': `
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def doubleIt(head):
    digits = []
    cur = head
    while cur:
        digits.append(cur.val)
        cur = cur.next
    carry = 0
    for i in range(len(digits) - 1, -1, -1):
        val = digits[i] * 2 + carry
        digits[i] = val % 10
        carry = val // 10
    if carry:
        digits.insert(0, carry)
    if not digits:
        return None
    new_head = ListNode(digits[0])
    cur = new_head
    for d in digits[1:]:
        cur.next = ListNode(d)
        cur = cur.next
    return new_head

def doubleItRunner(arr):
    if hasattr(arr, 'to_py'): arr = list(arr.to_py())
    arr = [int(x) for x in arr]
    if not arr:
        return []
    head = ListNode(arr[0])
    cur = head
    for v in arr[1:]:
        cur.next = ListNode(v)
        cur = cur.next
    result_head = doubleIt(head)
    result = []
    while result_head:
        result.append(result_head.val)
        result_head = result_head.next
    return result
`,

