  'throne-inheritance': `
def throneInheritance(operations, args):
    if hasattr(operations, 'to_py'): operations = list(operations.to_py())
    if hasattr(args, 'to_py'): args = list(args.to_py())
    results = []
    king = ''
    children = {}
    dead = set()
    for i in range(len(operations)):
        op = operations[i]
        arg = list(args[i]) if hasattr(args[i], 'to_py') else list(args[i])
        arg = [str(x) for x in arg]
        if op == 'ThroneInheritance':
            king = arg[0]
            children[king] = []
            results.append(None)
        elif op == 'birth':
            parent, child = arg[0], arg[1]
            children[parent].append(child)
            children[child] = []
            results.append(None)
        elif op == 'death':
            dead.add(arg[0])
            results.append(None)
        else:
            order = []
            stack = [king]
            while stack:
                name = stack.pop()
                if name not in dead:
                    order.append(name)
                ch = children.get(name, [])
                for c in reversed(ch):
                    stack.append(c)
            results.append(order)
    return results`,

