  'count-almost-equal-pairs-ii': `def countPairs(nums):
    if hasattr(nums, 'to_py'): nums = list(nums.to_py())
    nums = [int(x) for x in nums]
    PAD = 7
    def reachable(num):
        s = str(num).zfill(PAD)
        reached = {num}
        one_swaps = []
        chars = list(s)
        for i in range(PAD):
            for j in range(i + 1, PAD):
                t = chars[:]
                t[i], t[j] = t[j], t[i]
                joined = ''.join(t)
                reached.add(int(joined))
                one_swaps.append(joined)
        for s1 in one_swaps:
            chars1 = list(s1)
            for i in range(PAD):
                for j in range(i + 1, PAD):
                    t = chars1[:]
                    t[i], t[j] = t[j], t[i]
                    reached.add(int(''.join(t)))
        return reached
    count = 0
    n = len(nums)
    for i in range(n):
        reach = reachable(nums[i])
        for j in range(i + 1, n):
            if nums[j] in reach:
                count += 1
    return count
`,

  'design-phone-directory': `def phoneDirectory(operations, args):
    if hasattr(operations, 'to_py'): operations = list(operations.to_py())
    if hasattr(args, 'to_py'): args = list(args.to_py())
    results = []
    queue = []
    available = set()
    for i in range(len(operations)):
        op = str(operations[i])
        arg = list(args[i].to_py()) if hasattr(args[i], 'to_py') else list(args[i])
        if op == 'PhoneDirectory':
            n = int(arg[0])
            queue = list(range(n))
            available = set(range(n))
            results.append(None)
        elif op == 'get':
            while queue and queue[0] not in available:
                queue.pop(0)
            if not queue:
                results.append(-1)
            else:
                num = queue.pop(0)
                available.discard(num)
                results.append(num)
        elif op == 'check':
            results.append(int(arg[0]) in available)
        else:
            num = int(arg[0])
            if num not in available:
                available.add(num)
                queue.append(num)
            results.append(None)
    return results
`,

